// Fake fetch: any HTTP status resolves; only network failure rejects.
function fakeFetch(url) {
  return new Promise(function (resolve, reject) {
    if (url === '/offline') return reject(new TypeError('Failed to fetch'));
    const table = { '/ok': [200, '{"id":1}'], '/missing': [404, '{"error":"nope"}'],
                    '/empty': [204, ''], '/boom': [500, 'oops'] };
    const r = table[url];
    resolve({ status: r[0], ok: r[0] >= 200 && r[0] < 300,
              json: async () => JSON.parse(r[1]) });
  });
}
class HttpError extends Error {
  constructor(status) { super('HTTP ' + status); this.status = status; }
}
async function fetchJson(url) {
  const res = await fakeFetch(url);              // rejects only on network failure
  if (!res.ok) throw new HttpError(res.status);  // layer 2: HTTP errors
  if (res.status === 204) return null;           // no body to parse
  return res.json();
}
async function main() {
  for (const url of ['/ok', '/missing', '/empty', '/boom', '/offline']) {
    try {
      console.log(url, '->', JSON.stringify(await fetchJson(url)));
    } catch (e) {
      const kind = e instanceof HttpError ? '(status ' + e.status + ')' : '(network)';
      console.log(url, '-> error:', e.message, kind);
    }
  }
}
main();

// 'a' is slow (60 ms), 'ab' is fast (10 ms): responses arrive out of order.
const delays = { a: 60, ab: 10 };
function search(q) {
  return new Promise(function (r) { setTimeout(function () { r('results for ' + q); }, delays[q]); });
}
function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

async function run(guarded) {
  let shown = '(nothing)';
  let latest = 0;                       // sequence number of the newest request
  async function onInput(q) {
    const id = ++latest;                // remember which request this is
    const res = await search(q);
    if (guarded && id !== latest) {     // a newer request exists: drop this one
      console.log('  ignored stale:', res);
      return;
    }
    shown = res;
  }
  onInput('a');
  await sleep(5);
  onInput('ab');
  await sleep(100);
  console.log((guarded ? 'guarded' : 'naive') + ' shows:', shown);
}
(async function () {
  await run(false);   // naive: the old slow response overwrites the new one
  await run(true);    // guarded: only the latest response is rendered
})();

// Retry only errors that can help (network, 5xx), never 4xx.
function retryable(e) { return e.status === undefined || e.status >= 500; }

async function withRetry(fn, maxAttempts, base, cap, sleep) {
  for (let n = 0; ; n++) {
    try {
      return await fn();
    } catch (e) {
      if (n + 1 >= maxAttempts || !retryable(e)) throw e;
      const ceiling = Math.min(cap, base * 2 ** n);   // 100, 200, 400 ... capped
      console.log('attempt', n + 1, 'failed (' + e.message + '), waiting up to', ceiling, 'ms');
      await sleep(Math.random() * ceiling);           // full jitter spreads clients out
    }
  }
}
const noSleep = function () { return Promise.resolve(); };  // skip real waiting in the demo

