const DATA = Array.from({ length: 7 }, function (_, i) { return 'item' + (i + 1); });
function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
// Cursor-based page: returns 3 items and where to continue (null = end).
function fetchPage(cursor) {
  return sleep(5).then(function () {
    return { items: DATA.slice(cursor, cursor + 3),
             next: cursor + 3 < DATA.length ? cursor + 3 : null };
  });
}
const list = [];
let cursor = 0, loading = false, hasMore = true, fetches = 0;

// Called every time the sentinel becomes visible.
async function onSentinelVisible() {
  if (loading || !hasMore) return;      // guard: no double fetch, no fetch at the end
  loading = true;
  try {
    fetches++;
    const page = await fetchPage(cursor);
    list.push(...page.items);
    if (page.next === null) hasMore = false; else cursor = page.next;
  } finally {
    loading = false;                    // always clear the flag, even on error
  }
}
async function main() {
  onSentinelVisible(); onSentinelVisible(); onSentinelVisible();  // 3 rapid triggers
  await sleep(20);
  console.log('after 3 rapid triggers:', list.length, 'items,', fetches, 'fetches');
  while (hasMore) await onSentinelVisible();
  await onSentinelVisible();            // ignored: nothing more to load
  console.log('final:', list.length, 'items,', fetches, 'fetches, hasMore=' + hasMore);
  console.log(list.join(','));
}
main();

// Compile '/users/:id' into a regex plus the list of parameter names.
function compile(pattern) {
  const names = [];
  const src = pattern.replace(/:([A-Za-z]+)/g, function (_, n) { names.push(n); return '([^/]+)'; });
  return { pattern: pattern, re: new RegExp('^' + src + '/?$'), names: names };
}
const routes = ['/', '/users/:id', '/users/:id/posts/:postId'].map(compile);

function match(url) {
  const u = new URL(url, 'http://localhost');       // parses path and query for us
  for (const r of routes) {
    const m = r.re.exec(u.pathname);
    if (m) {
      const params = {};
      r.names.forEach(function (n, i) { params[n] = decodeURIComponent(m[i + 1]); });
      return { route: r.pattern, params: params, query: Object.fromEntries(u.searchParams) };
    }
  }
  return { route: '404' };                          // not-found route
}
