let networkCalls = 0;
function fakeApi(key) {
  networkCalls++;
  const version = networkCalls;
  return new Promise(function (r) { setTimeout(function () { r(key + '@v' + version); }, 10); });
}
const cache = new Map();      // key -> { data, at }
const inflight = new Map();   // key -> promise already on its way

function get(key, ttl, now) {
  const hit = cache.get(key);
  if (hit && now - hit.at < ttl) {                 // fresh: serve from cache
    return Promise.resolve({ data: hit.data, from: 'cache' });
  }
  if (inflight.has(key)) return inflight.get(key); // dedupe: share the same request
  const p = fakeApi(key).then(function (data) {
    cache.set(key, { data: data, at: now });
    inflight.delete(key);
    return { data: data, from: 'network' };
  });
  inflight.set(key, p);
  return p;
}
async function main() {
  const three = await Promise.all([get('user:1', 100, 0), get('user:1', 100, 0), get('user:1', 100, 0)]);
  console.log('3 concurrent:', JSON.stringify(three[0]), 'network calls =', networkCalls);
  console.log('t=50 :', JSON.stringify(await get('user:1', 100, 50)), 'calls =', networkCalls);
  console.log('t=200:', JSON.stringify(await get('user:1', 100, 200)), 'calls =', networkCalls);
}
main();
